import type { AtRule, Declaration, Rule } from "postcss";
import { type Edit } from "../applyEditsFromEnd/index.ts";
import type { CommentReading } from "../findCommentSpans/index.ts";
/**
 * Finds the `(` of the address's token holding an index, as the tokenizer walks the text from its opening ({@link walkToParenthesis}); an address nothing closes holds every index behind its `(`.
 * @param text - The text read.
 * @param index - The index.
 * @param reading - Whether the parser reads by a tokenizer of its own.
 * @returns The `(`, or -1 where no address's token holds the index.
 */
export declare function addressHolding(text: string, index: number, reading: Pick<CommentReading, `tokenizes`>): number;
/**
 * Asks whether an edit makes the tokenizer read the parentheses of a `url(` right behind it the other way, where the parser then builds other nodes.
 *
 * PostCSS's tokenizer, which `postcss-less` reads by too, takes the parentheses as one token where the word it pops at the `(` is `url` itself ({@link openingParenthesisBehind}), and as code where that word is longer; `1,url(` and `1/url(` are one word to it, so filling or emptying the run in front of the name switches the reading. A quotation mark or whitespace right behind the `(` makes the parentheses code under both words.
 *
 * `postcss-scss`'s tokenizer ends a word on a comma outside an at-word, so such a comma's run switches nothing under it, and a comma, an interpolation or a `//` comment between the name and the `(` pushes no word under it either. Its token opens behind whitespace too, a quotation mark right behind the `(` alone keeping the parentheses code, and closes by the count of parentheses.
 *
 * Where the reading switches, both texts are walked whole ({@link parsesPart}), and the edit is refused only where the output reads otherwise: it stops parsing, a group is left open or closed, a `)` closing the token in front of the one code closes the parentheses at lets a `;` or a brace out of the group code holds it in, or a colon or a comma the parser or the rules then read otherwise ({@link readsTheCutAlike}), or a string or a comment is lost ({@link losesASpan}). A group code reads inside the parentheses costs nothing by itself, since the parser passes over the `)` the token leaves unpaired.
 *
 * The value parser reads a declaration the tokenizer reads by a tokenizer of its own with neither the probe's nor the tokenizer's parentheses: it closes a split `url` at the first `)`, so a comma the tokenizer kept inside the address stands in the output inside the call around it, and the `function-comma-*` rules read it where the input held none ({@link commasReadDifferently}); only the direction that adds a read comma is refused, and an at-rule's params are read by no such rule, the media-query-list comma rule reading its lists by paren depth, so a run written there or in a selector never moves a comma it reads.
 * @param text - The text the edit applies to.
 * @param edit - The edit, indexed in that text.
 * @param edit.start - Where the span it replaces opens.
 * @param edit.end - Where that span closes.
 * @param edit.text - What it writes there.
 * @param reading - Whether the parser reads by a tokenizer of its own.
 * @param node - The node the text is read from, which says what the parser and the rules read in it.
 * @returns True where the edit switches the reading of parentheses and the parser builds other nodes out of the output.
 */
export declare function rereadsAnAddress(text: string, { start, end, text: written }: Edit, reading: Pick<CommentReading, `tokenizes`>, node: AtRule | Declaration | Rule): boolean;
/**
 * Asks whether the edits of a fix make the tokenizer read the parentheses of an address the other way, where the two readings part.
 *
 * The parentheses a `(` pops `url` at are one token, and what stands right behind that `(` is what keeps them code instead ({@link keepsParenthesesCode}), so a run written there can switch the reading. So can a line break written into parentheses the tokenizer takes as one plain token anywhere in front: it reads them as code, pushes the words inside them, and a later `(` pops one of those where it popped `url`, or the other way round when a break is taken out. The call is the parser's rather than the compilers': `\61 url(` and `x\9 url(` name one call, `aurl` and `xurl`, to Sass and to `lightningcss`, and the value-parser rules read them as one ({@link opensAnAddress}), while the tokenizer sees the three characters `url` right against the `(` and takes the parentheses for an address's.
 *
 * Both texts are walked whole ({@link addressOpenings}), and where an address's token opens at another `(` in one of them, they are compared as {@link rereadsAnAddress} compares them ({@link parsesPart}), and the edits are refused where the model of cuts reads the output otherwise: a `)` closing the token in front of the one code closes the parentheses at lets a `;` or a brace out of the group code holds it in, or a colon or a comma the parser or the rules then read otherwise ({@link readsTheCutAlike}), a group or a token is left open or closed, or a string or a comment is lost. Otherwise the two readings part only in which parentheses are one token, which changes no text the parser reads back.
 * @param text - The text the edits apply to.
 * @param edits - The edits the fix writes inside a call's parentheses, indexed in that text.
 * @param reading - Whether the parser reads by a tokenizer of its own.
 * @param node - The node the text is read from, which says what the parser and the rules read in it.
 * @returns True where the edits switch the reading of an address's parentheses and the parser builds other nodes out of the output.
 */
export declare function editsRereadAnAddress(text: string, edits: Edit[], reading: Pick<CommentReading, `tokenizes`>, node: AtRule | Declaration | Rule): boolean;
